package com.truckgo.storage;

import java.io.InputStream;
import java.time.Instant;
import java.util.List;

/**
 * Private object storage. Keys are always generated by the server; callers never pass user-supplied paths.
 * Implementations throw {@link StorageUnavailableException} when the backend cannot be reached.
 */
public interface StorageService {
    void put(String key, InputStream data, long size, String contentType);

    /** Caller must close the stream. */
    InputStream get(String key);

    /** Idempotent: deleting a key that does not exist succeeds. */
    void delete(String key);

    record StoredObject(String key, Instant lastModified, long size) { }

    /** Up to max objects under prefix, in key order, strictly after startAfter (null = from the beginning). */
    List<StoredObject> list(String prefix, String startAfter, int max);
}
